    <script>(function(){var dlg=document.getElementById('user-status-dialog'),form=document.getElementById('user-status-form');if(!dlg||!form)return;document.querySelectorAll('[data-user-menu-toggle]').forEach(function(btn){btn.addEventListener('click',function(){var menu=document.getElementById(btn.getAttribute('aria-controls'));document.querySelectorAll('[data-user-menu-toggle]').forEach(function(other){if(other!==btn){other.setAttribute('aria-expanded','false');var m=document.getElementById(other.getAttribute('aria-controls'));if(m)m.hidden=true;}});var open=btn.getAttribute('aria-expanded')==='true';btn.setAttribute('aria-expanded',open?'false':'true');menu.hidden=open;if(!open){var trigger=btn.getBoundingClientRect(),size=menu.getBoundingClientRect(),top=trigger.bottom+4,left=trigger.left,maxTop=window.innerHeight-size.height-8,maxLeft=window.innerWidth-size.width-8;if(top+size.height>window.innerHeight-8){if(trigger.top-size.height-4>=8)top=trigger.top-size.height-4;else top=maxTop;}top=Math.max(8,Math.min(top,maxTop));left=Math.max(8,Math.min(trigger.right-size.width,maxLeft));menu.style.top=top+'px';menu.style.left=left+'px';var first=menu.querySelector('[role="menuitem"]');if(first)first.focus();}});});document.addEventListener('click',function(e){if(!e.target.closest('[data-user-menu-toggle]')&&!e.target.closest('[role="menu"]'))document.querySelectorAll('[data-user-menu-toggle]').forEach(function(btn){btn.setAttribute('aria-expanded','false');var m=document.getElementById(btn.getAttribute('aria-controls'));if(m)m.hidden=true;});});document.querySelectorAll('[data-user-status-open]').forEach(function(btn){btn.addEventListener('click',function(){var blocked=btn.dataset.userBlocked==='1';document.getElementById('user-status-id').value=btn.dataset.userId;document.getElementById('user-status-tenant').value=btn.dataset.userTenantId;document.getElementById('user-status-flag').value=blocked?'0':'1';document.getElementById('user-status-name').textContent=btn.dataset.userName;var confirm=document.getElementById('user-status-confirm');confirm.classList.toggle('bg-rose-600',!blocked);confirm.classList.toggle('hover:bg-rose-700',!blocked);confirm.classList.toggle('bg-emerald-600',blocked);confirm.classList.toggle('hover:bg-emerald-700',blocked);dlg.showModal();});});document.querySelector('[data-user-status-cancel]').addEventListener('click',function(){dlg.close();});dlg.addEventListener('click',function(e){if(e.target===dlg)dlg.close();});})();</script><?php endif; ?>
<script>(function(){var header=document.querySelector('[data-user-filter-header]'),columnFilterToggle=document.querySelector('[data-user-column-filter-toggle]'),columnFilterPanel=document.getElementById('user-column-filter-panel'),searchForm=document.querySelector('[data-user-live-filter]'),searchInput=searchForm&&searchForm.querySelector('[name="search"]'),columnIcon=columnFilterToggle&&columnFilterToggle.querySelector('[data-user-filter-icon-columns]'),searchIcon=columnFilterToggle&&columnFilterToggle.querySelector('[data-user-filter-icon-search]'),timer=null;if(columnFilterToggle&&columnFilterPanel){function setMode(showColumns){if(searchForm){searchForm.hidden=showColumns;searchForm.classList.toggle('hidden',showColumns);}columnFilterPanel.hidden=!showColumns;columnFilterPanel.classList.toggle('hidden',!showColumns);columnFilterToggle.setAttribute('aria-expanded',showColumns?'true':'false');var label=showColumns?columnFilterToggle.getAttribute('data-label-search'):columnFilterToggle.getAttribute('data-label-columns');columnFilterToggle.setAttribute('aria-label',label);columnFilterToggle.setAttribute('title',label);if(columnIcon){columnIcon.toggleAttribute('hidden',showColumns);columnIcon.classList.toggle('hidden',showColumns);}if(searchIcon){searchIcon.toggleAttribute('hidden',!showColumns);searchIcon.classList.toggle('hidden',!showColumns);}}columnFilterToggle.addEventListener('click',function(){var showColumns=columnFilterPanel.hidden;setMode(showColumns);if(showColumns){var field=columnFilterPanel.querySelector('select');if(field)field.focus();}else if(searchInput){searchInput.focus();}});document.addEventListener('click',function(event){if(header&&!header.contains(event.target)&&columnFilterToggle.getAttribute('aria-expanded')==='true'){setMode(false);}});document.addEventListener('keydown',function(event){if(event.key==='Escape'&&columnFilterToggle.getAttribute('aria-expanded')==='true'){setMode(false);columnFilterToggle.focus();}});}if(searchForm&&searchInput){searchInput.addEventListener('input',function(){window.clearTimeout(timer);timer=window.setTimeout(function(){if(typeof searchForm.requestSubmit==='function')searchForm.requestSubmit();else searchForm.submit();},350);});}})();</script>
    <script>(function(){document.querySelectorAll('[data-api-secret-copy]').forEach(function(button){button.addEventListener('click',async function(){var row=button.closest('tr'),csrf=row&&row.querySelector('form[action="/admin/application/user/delete"] input[type="hidden"]'),label=button.getAttribute('aria-label');if(!csrf){button.setAttribute('aria-label',button.dataset.copyError);return;}button.disabled=true;try{var payload=new URLSearchParams();payload.set(csrf.name,csrf.value);payload.set('user_id',button.dataset.userId);payload.set('tenant_id',button.dataset.tenantId);var response=await fetch('/admin/application/user/api-secret',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','X-Requested-With':'XMLHttpRequest'},body:payload.toString()});if(!response.ok)throw new Error('request failed');var data=await response.json();if(data.csrf&&typeof data.csrf.name==='string'&&typeof data.csrf.hash==='string'){document.querySelectorAll('input[type="hidden"]').forEach(function(input){if(input.name===data.csrf.name)input.value=data.csrf.hash;});}if(typeof data.secret!=='string'||!data.secret)throw new Error('invalid response');if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(data.secret);}else{var area=document.createElement('textarea');area.value=data.secret;area.setAttribute('readonly','');area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();var copied=document.execCommand('copy');area.remove();if(!copied)throw new Error('clipboard unavailable');}button.setAttribute('aria-label',button.dataset.copySuccess);button.title=button.dataset.copySuccess;window.setTimeout(function(){button.setAttribute('aria-label',label);button.removeAttribute('title');},2200);}catch(error){button.setAttribute('aria-label',button.dataset.copyError);button.title=button.dataset.copyError;window.setTimeout(function(){button.setAttribute('aria-label',label);button.removeAttribute('title');},3000);}finally{button.disabled=false;}});});})();</script>
